// src/components/ReviewModal.js

import React, { useState, useEffect } from 'react';
import Modal from 'react-modal';
import MovieSearchBar from './MovieSearchBar';
import { getPosterFromTMDB } from '../api/tmdbApi';

Modal.setAppElement('#root');

// ⭐️ prop 이름을 'date'에서 'selectedDate'로 변경하여 명확성 증대
function ReviewModal({ isOpen, onRequestClose, selectedDate, existingReview, onSave, onDelete }) {
  const [selectedMovie, setSelectedMovie] = useState(null);
  const [posterPath, setPosterPath] = useState('');
  const [reviewText, setReviewText] = useState('');

  useEffect(() => {
    // 모달이 열릴 때, 전달된 리뷰 데이터에 따라 상태를 설정
    if (existingReview) {
      setSelectedMovie(existingReview.movie);
      setPosterPath(existingReview.posterPath);
      setReviewText(existingReview.reviewText);
    } else {
      // 새 리뷰 작성을 위해 모든 관련 상태를 깨끗하게 초기화
      setSelectedMovie(null);
      setPosterPath('');
      setReviewText('');
    }
  }, [existingReview]); // ⭐️ 의존성 배열을 existingReview만으로 단순화

  const handleMovieSelect = async (movie) => {
    setSelectedMovie(movie);
    const year = movie.openDt?.substring(0, 4) || '';
    const poster = await getPosterFromTMDB(movie.movieNm, year, {
      movieNmEn: movie.movieNmEn,
      nation: movie.repNationNm,
    });
    setPosterPath(poster || '');
  };

  const handleSave = () => {
    if (!selectedMovie) {
      alert('영화를 선택해주세요.');
      return;
    }
    onSave({
      date: selectedDate, // 저장 시에는 selectedDate prop 사용
      movie: selectedMovie,
      reviewText,
      posterPath,
    });
    onRequestClose();
  };

  const handleDelete = () => {
    if (window.confirm('정말로 이 리뷰를 삭제하시겠습니까?')) {
      onDelete(selectedDate); // 삭제 시에도 selectedDate prop 사용
      onRequestClose();
    }
  };
  
  // ⭐️ 영화 변경 시 모든 관련 상태를 초기화하는 함수
  const handleChangeMovie = () => {
    setSelectedMovie(null);
    setPosterPath('');
    setReviewText('');
  };

  return (
    <Modal
      isOpen={isOpen}
      onRequestClose={onRequestClose}
      className="review-modal"
      overlayClassName="review-modal-overlay"
    >
      <h2>{selectedDate.toLocaleDateString()} 관람 기록</h2>

      {!selectedMovie ? (
        <MovieSearchBar onMovieSelect={handleMovieSelect} />
      ) : (
        <div className="selected-movie-info">
          {posterPath && <img src={posterPath} alt={selectedMovie.movieNm} />}
          <div className="movie-text-info">
            <h3>{selectedMovie.movieNm}</h3>
            {/* ⭐️ 영화 변경 버튼에 새로운 핸들러 연결 */}
            <button onClick={handleChangeMovie} className="change-movie-btn">영화 변경</button>
          </div>
        </div>
      )}

      <textarea
        value={reviewText}
        onChange={(e) => setReviewText(e.target.value)}
        placeholder="자유롭게 리뷰를 남겨보세요..."
        rows="6"
      />

      <div className="modal-buttons">
        {existingReview && <button onClick={handleDelete} className="delete-btn">삭제</button>}
        <div style={{ flexGrow: 1 }} />
        <button onClick={onRequestClose} className="cancel-btn">취소</button>
        <button onClick={handleSave} className="save-btn">저장</button>
      </div>
    </Modal>
  );
}

export default ReviewModal;
